const n=v=>{const x=parseFloat(v);return isNaN(x)?0:x};
const f=(v,d=2)=>(v<0?'−':'')+Math.abs(v).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const lossMakers=SBUS.filter(s=>s.deficit>0);
const lossSBUs=SBUS.filter(s=>s.loss>0);
const TOT={def:n(lossMakers.reduce((a,s)=>a+s.deficit,0).toFixed(2)),loss:n(lossSBUs.reduce((a,s)=>a+s.loss,0).toFixed(2)),commit:n(lossMakers.reduce((a,s)=>a+s.commit,0).toFixed(2))};
TOT.cov=TOT.commit/TOT.def*100;
const covOf=s=>s.commit==null?null:(s.commit/s.deficit*100);

function svgTrend(s){
  const w=250,h=122,padL=40,padB=20,padT=18,padR=6;
  const keys=['jul','aug','sep'],labels=['Jul','Aug','Sep'];
  const budgets=keys.map(k=>s.rev[k].b), actuals=keys.map(k=>s.rev[k].a);
  const max=Math.max(...budgets,...actuals,1)*1.12;
  const plotW=w-padL-padR,plotH=h-padT-padB;
  const x=i=>padL+(i+0.5)*(plotW/3);
  const y=v=>padT+plotH*(1-v/max);
  const sv=v=>{const t=v<10?v.toFixed(2):v.toFixed(1);return t.replace(/\.?0+$/,'');};
  let g=`<svg viewBox="0 0 ${w} ${h}" width="100%" role="img" aria-label="Monthly revenue budget vs actual">`;
  for(let i=0;i<=3;i++){const gy=padT+plotH*i/3;g+=`<line x1="${padL}" y1="${gy}" x2="${w-padR}" y2="${gy}" stroke="#eef2f7"/>`;g+=`<text x="${padL-4}" y="${gy+3}" text-anchor="end" font-size="8" fill="#94a3b8">${(max*(1-i/3)).toFixed(0)} Cr</text>`;}
  const bw=Math.min(20,plotW/3*0.22);
  keys.forEach((k,i)=>{const cx=x(i);
    g+=`<rect x="${cx-bw-2}" y="${y(budgets[i])}" width="${bw}" height="${plotH-(y(budgets[i])-padT)}" fill="#cbd5e1" rx="2"/>`;
    g+=`<rect x="${cx+2}" y="${y(actuals[i])}" width="${bw}" height="${plotH-(y(actuals[i])-padT)}" fill="#0e7490" rx="2"/>`;
    if(budgets[i]>0.01)g+=`<text x="${cx-2-bw/2}" y="${y(budgets[i])-3}" text-anchor="middle" font-size="6.5" fill="#94a3b8">${sv(budgets[i])}</text>`;
    if(actuals[i]>0.01)g+=`<text x="${cx+2+bw/2}" y="${y(actuals[i])-3}" text-anchor="middle" font-size="6.5" font-weight="700" fill="#0e7490">${sv(actuals[i])}</text>`;
    g+=`<text x="${cx}" y="${h-7}" text-anchor="middle" font-size="8" fill="#64748b">${labels[i]}</text>`;});
  g+='</svg>';
  return g;
}

