function renderMenu(){
  const top=`
    <button class="menu-item" data-t="md" title="Direction per SBU + top 5 decisions"><span class="serial">★</span><span class="dot" style="background:#111827"></span><span class="nm">MD Brief</span></button>
    <button class="menu-item" data-t="overview" title="Portfolio overview"><span class="serial">▦</span><span class="dot" style="background:#94a3b8"></span><span class="nm">Overview</span></button>
    <button class="menu-item" data-t="market" title="Market share & lost-dealer regions"><span class="serial">◔</span><span class="dot" style="background:#7c3aed"></span><span class="nm">Market Share</span></button>
    <button class="menu-item" data-t="sales" title="Sales team KPI & dealer engagement"><span class="serial">◑</span><span class="dot" style="background:#0f766e"></span><span class="nm">Sales KPI</span></button>
    <button class="menu-item" data-t="rootcause" title="Root-cause verdicts H1–H9"><span class="serial">✓</span><span class="dot" style="background:#dc2626"></span><span class="nm">Root Cause</span></button>
    
    <button class="menu-item" data-t="loss" title="Budget to actual loss bridge"><span class="serial">▤</span><span class="dot" style="background:#dc2626"></span><span class="nm">Loss Bridge</span></button>
    <button class="menu-item" data-t="game" title="2x2 payoff vs the main gainer"><span class="serial">◈</span><span class="dot" style="background:#4f46e5"></span><span class="nm">Competitive Game</span></button>
    <button class="menu-item" data-t="sim" title="Price, volume and COGS simulator"><span class="serial">△</span><span class="dot" style="background:#0891b2"></span><span class="nm">Simulator</span></button>
    <button class="menu-item" data-t="data" title="Data status by Data ID"><span class="serial">▤</span><span class="dot" style="background:#64748b"></span><span class="nm">Data Status</span></button>
    <div class="menu-label" style="margin-top:10px">Loss-making SBUs</div>`;
  const items=SBUS.map((s,i)=>{
    const dot=`<span class="dot" style="background:${TONEC[s.verdict.tone]}"></span>`;
    const loss=s.loss>0?`<span class="loss">−${f(s.loss)}</span>`:'<span class="loss surplus">surplus</span>';
    const tip=`${s.name} — ${s.loss>0?'−'+s.loss.toFixed(2)+' Cr loss':'surplus'}`;
    return `<button class="menu-item" data-t="${s.code}" title="${tip}"><span class="serial">${i+1}</span>${dot}<span class="nm">${s.name}</span>${loss}</button>`;
  }).join('');
  document.getElementById('menu').innerHTML=top+items;
  document.querySelectorAll('.menu-item').forEach(b=>b.addEventListener('click',()=>switchPage(b.dataset.t)));
  const btn=document.getElementById('collapseBtn');
  btn.addEventListener('click',()=>{
    const sb=document.querySelector('.sidebar');
    sb.classList.toggle('collapsed');
    btn.textContent=sb.classList.contains('collapsed')?'»':'«';
  });
}
const FIXED_PAGES=['md','overview','market','sales','rootcause','loss','game','sim','data'];
function switchPage(k){
  document.querySelectorAll('.menu-item').forEach(b=>b.classList.toggle('active',b.dataset.t===k));
  const target=FIXED_PAGES.includes(k)?'pane-'+k:'pane-sbu-'+k;
  document.querySelectorAll('.pane').forEach(p=>p.classList.toggle('active',p.id===target));
  window.scrollTo({top:0});
}

